mapper.select:
SELECT
(SELECT count(id) FROM base_company WHERE
date_format(create_time,'%Y-%m') = date_format(now(),'%Y-%m')

    AND fid_region = #{fidRegion}

) as monthNum,
count(id) as total
FROM base_company
where create_time is not null

    AND fid_region = #{fidRegion}

SELECT
(SELECT count(id) FROM base_point WHERE
date_format(create_time,'%Y-%m') = date_format(now(),'%Y-%m')

    AND fid_region = #{fidRegion}

) as monthNum,
count(id) as total
FROM base_point
where create_time is not null

    AND fid_region = #{fidRegion}

SELECT
    (SELECT count(1) FROM base_point

            WHERE fid_region = #{fidRegion}

    ) as total,
    COUNT(sub.mac) as onlineTime,
    ((SELECT count(1) FROM base_point

            WHERE fid_region = #{fidRegion}

    ) - COUNT(sub.mac))offline
FROM(
    SELECT BP.point_mac as mac
    FROM base_point BP
    INNER JOIN ${table} BLD on BLD.point_mac = BP.point_mac
    WHERE 1=1

            and BP.fid_region = #{fidRegion}

        and BLD.create_time between date_add(now(), interval  #{hours}  hour) and now()
    GROUP BY BP.point_mac
) sub

SELECT count(1) FROM base_company BC WHERE BC.id in(SELECT company_id FROM base_point GROUP BY company_id)
AND date_format(BC.create_time,'%Y-%m') = date_format(now(),'%Y-%m')
AND BC.fid_region = #{fidRegion}

SELECT
(SELECT COUNT(CASE business_category WHEN 1 THEN 0 END)) as A类, (SELECT COUNT(CASE business_category WHEN 2 THEN 0 END)) as B类, (SELECT COUNT(CASE business_category WHEN 3 THEN 0 END)) as C类, (SELECT COUNT(CASE business_category WHEN 4 THEN 0 END)) as D类, (SELECT COUNT(CASE business_category WHEN 5 THEN 0 END)) as E类 FROM base_company
WHERE fid_region = #{fidRegion}

SELECT
(SELECT COUNT(CASE unit_category WHEN 1 THEN 0 END)) as 餐饮经营单位, (SELECT COUNT(CASE unit_category WHEN 2 THEN 0 END)) as 单位食堂, (SELECT COUNT(CASE unit_category WHEN 3 THEN 0 END)) as 中央厨房, (SELECT COUNT(CASE unit_category WHEN 4 THEN 0 END)) as 集体用餐配送单位 FROM base_company
WHERE fid_region = #{fidRegion}
